def sum(self):
    if isinstance(self.data, list):
        out_data = sum(self.data)
    else:
        out_data = self.data
    _ensure_finite_data(out_data)
    if not self.requires_grad:
        return Tensor._make(out_data, False, (), None)
    parent = self

    def backward_fn(grad):
        if isinstance(parent.data, list):
            return [(parent, [grad] * len(parent.data))]
        return [(parent, grad)]

    return Tensor._make(out_data, True, (parent,), backward_fn)

def prod(self):
    # Re-validate at call time since the data may have been mutated
    # after construction: a finite float scalar or a non-empty 1D
    # float list. bools, ints and other types are a TypeError; an
    # empty list or any non-finite value is a ValueError.
    data = _validate_data(self.data)
    if not isinstance(self.requires_grad, bool):
        raise TypeError("requires_grad must be a bool")
    if isinstance(data, list):
        # Accumulate from 1.0 in ascending index order; a non-finite
        # partial product aborts before a result tensor exists, so no
        # state can change on failure.
        acc = 1.0
        for value in data:
            acc *= value
            if not math.isfinite(acc):
                raise ValueError("prod intermediate must be finite")
        out_data = acc
    else:
        # A scalar's product is the scalar itself.
        out_data = data
    if not self.requires_grad:
        return Tensor._make(out_data, False, (), None)
    parent = self
    # _validate_data already returns a fresh list for vector input,
    # so `data` is a snapshot: later caller-side mutation or
    # replacement of the input cannot change a pending backward pass.
    snapshot = data

    def backward_fn(grad):
        # Scalar input: the contribution is g itself. Vector input:
        # element i receives g times the product of every x[j] with
        # j != i, accumulated from 1.0 in ascending index order; a
        # single-element vector therefore gets the empty product 1.0
        # and zero elements contribute their mathematical product.
        if not isinstance(snapshot, list):
            return [(parent, grad)]
        contribution = []
        for i in range(len(snapshot)):
            cofactor = 1.0
            for j in range(len(snapshot)):
                if j == i:
                    continue
                cofactor *= snapshot[j]
                if not math.isfinite(cofactor):
                    raise ValueError(
                        "prod backward intermediate must be finite"
                    )
            value = cofactor * grad
            if not math.isfinite(value):
                raise ValueError(
                    "prod backward intermediate must be finite"
                )
            contribution.append(value)
        return [(parent, contribution)]

    return Tensor._make(out_data, True, (parent,), backward_fn)

def cumprod(self):
    # One-dimensional prefix product. Re-validate at call time since
    # the data may have been mutated after construction: data must be
    # a non-empty 1D list of finite floats (anything that is not a
    # list, including a scalar, and an empty list are ValueError; a
    # non-float element is TypeError), and requires_grad must be a
    # bool (TypeError); non-finite elements are ValueError.
    data = self.data
    if not isinstance(data, list) or len(data) == 0:
        raise ValueError("cumprod requires a non-empty 1D float list")
    for value in data:
        if isinstance(value, bool) or not isinstance(value, float):
            raise TypeError("cumprod data elements must be floats")
    if not isinstance(self.requires_grad, bool):
        raise TypeError("requires_grad must be a bool")
    for value in data:
        if not math.isfinite(value):
            raise ValueError("cumprod data elements must be finite")
    # Snapshot the input so later caller-side mutation or replacement
    # of self.data changes neither the forward result nor a pending
    # backward pass.
    snapshot = list(data)
    n = len(snapshot)
    # y[i] = prod x[0:i+1], accumulated from 1.0 in ascending i
    # order; a non-finite partial product aborts before a result
    # tensor exists, so the input and all graph state stay untouched.
    out_data = []
    acc = 1.0
    for i in range(n):
        acc *= snapshot[i]
        if not math.isfinite(acc):
            raise ValueError("cumprod intermediate must be finite")
        out_data.append(acc)
    if not self.requires_grad:
        return Tensor._make(
            out_data, False, (), None,
            grad_validator=lambda g: _validate_vector_grad(g, n),
        )
    parent = self

    def backward_fn(grad):
        # dx[j] = sum over i = j..n-1 of
        #   g[i] * prod(x[0:i+1] excluding x[j]),
        # i ascending, each dx[j] accumulated from 0.0. The cofactor
        # is rebuilt straight from the snapshot in strictly ascending
        # k order (never y[i] / x[j]), so zero elements differentiate
        # naturally. A non-finite cofactor term, partial product,
        # contribution or partial sum aborts the whole pass before
        # any grad is written.
        dx = [0.0] * n
        for j in range(n):
            total = 0.0
            for i in range(j, n):
                cofactor = 1.0
                for k in range(i + 1):
                    if k == j:
                        continue
                    cofactor *= snapshot[k]
                    if not math.isfinite(cofactor):
                        raise ValueError(
                            "cumprod backward intermediate must be finite"
                        )
                term = grad[i] * cofactor
                if not math.isfinite(term):
                    raise ValueError(
                        "cumprod backward intermediate must be finite"
                    )
                total += term
                if not math.isfinite(total):
                    raise ValueError(
                        "cumprod backward intermediate must be finite"
                    )
            dx[j] = total
            if not math.isfinite(dx[j]):
                raise ValueError(
                    "cumprod backward intermediate must be finite"
                )
        return [(parent, dx)]

    return Tensor._make(
        out_data, True, (parent,), backward_fn,
        grad_validator=lambda g: _validate_vector_grad(g, n),
    )

